import itertools
from typing import Dict, List, Tuple
from problems import HamiltonianCycle

def is_hamiltonian(instance: Dict) -> bool:
    HamiltonianCycle.validate(instance)
    n = instance["n"]
    edges = {frozenset(e) for e in instance["edges"]}
    if n <= 2:
        return False
    # generate permutations fixing first vertex to reduce symmetry
    vertices = list(range(n))
    for perm in itertools.permutations(vertices[1:]):
        path = (0,) + perm
        ok = True
        for i in range(n):
            u = path[i]
            v = path[(i + 1) % n]
            if frozenset((u, v)) not in edges:
                ok = False
                break
        if ok:
            return True
    return False
EOF"}

