{"command":"cat <<'EOF' > sat_solver.py
import itertools
from typing import Dict, List
from problems import Sat

def is_sat(instance: Dict) -> bool:
    Sat.validate(instance)
    m = instance["num_vars"]
    clauses: List[List[int]] = instance["clauses"]
    # if any empty clause -> unsat
    for cl in clauses:
        if len(cl) == 0:
            return False
    # brute force over assignments
    for bits in itertools.product([False, True], repeat=m):
        assignment = {i+1: bits[i] for i in range(m)}
        ok = True
        for clause in clauses:
            clause_sat = False
            for lit in clause:
                var = abs(lit)
                val = assignment[var]
                if lit > 0 and val:
                    clause_sat = True
                    break
                if lit < 0 and not val:
                    clause_sat = True
                    break
            if not clause_sat:
                ok = False
                break
        if ok:
            return True
    return False
EOF"}

